/**
 * Lecture + validation des variables d'environnement au démarrage.
 *
 * Principe non négociable (voir expert-createur-logiciel) : on refuse de
 * démarrer plutôt que de dégrader silencieusement. Un secret manquant est
 * une erreur de configuration, pas un cas à "gérer gracieusement" en
 * démarrant quand même avec des permissions floues.
 */
function required(name) {
    const v = process.env[name];
    if (!v || v.trim() === '') {
        throw new Error(`[config] Variable d'environnement manquante ou vide : ${name}. ` +
            `Voir .env.example. Le serveur refuse de démarrer.`);
    }
    return v;
}
function optional(name, fallback) {
    const v = process.env[name];
    return v && v.trim() !== '' ? v : fallback;
}
function bool(name, fallback) {
    const v = process.env[name];
    if (v === undefined)
        return fallback;
    return v.trim().toLowerCase() === 'true';
}
function int(name, fallback) {
    const v = process.env[name];
    if (!v)
        return fallback;
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
}
let cached = null;
export function loadConfig() {
    if (cached)
        return cached;
    const cfg = {
        mcpBearerToken: required('MCP_BEARER_TOKEN'),
        maBaseUrl: required('MA_BASE_URL').replace(/\/+$/, ''),
        maAgentKey: required('MA_AGENT_KEY'),
        maAgentId: optional('MA_AGENT_ID', 'claude-cowork-agent'),
        allowTier2: bool('MA_ALLOW_TIER2', false),
        agentEnabled: bool('AGENT_ENABLED', true),
        timeoutMs: int('MA_TIMEOUT_MS', 15000),
        cacheTtlMs: int('MA_CACHE_TTL_MS', 5 * 60 * 1000),
        logFile: optional('MA_LOG_FILE', './agent-actions.jsonl'),
        allowedClients: process.env.AGENT_ALLOWED_CLIENTS
            ? process.env.AGENT_ALLOWED_CLIENTS.split(',').map((s) => s.trim()).filter(Boolean)
            : null,
    };
    if (cfg.mcpBearerToken.length < 32) {
        throw new Error('[config] MCP_BEARER_TOKEN est trop court (< 32 caractères). Génère un secret plus long.');
    }
    cached = cfg;
    return cfg;
}

import { createApp } from './server.js';
const PORT = Number(process.env.PORT ?? 8787);
const { app, config, logger } = createApp();
app.listen(PORT, () => {
    logger.info('server_started', {
        port: PORT,
        tier2Enabled: config.allowTier2,
        agentEnabled: config.agentEnabled,
        maBaseUrl: config.maBaseUrl,
    });
    // eslint-disable-next-line no-console
    console.error(`marc-andre-mcp à l'écoute sur :${PORT} (endpoint MCP : /mcp)`);
});

import express from 'express';
import { randomUUID } from 'node:crypto';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
import { loadConfig } from './config.js';
import { Logger } from './core/logger.js';
import { MarcAndreHttpClient } from './core/httpClient.js';
import { requireBearerAuth, requireAgentEnabled } from './core/auth.js';
import { registerAllTools } from './tools/registry.js';
import { sweepExpiredIntents } from './confirm/intents.js';
/**
 * Serveur hébergé (décision D9), transport MCP « Streamable HTTP ».
 *
 * ⚠️ Note de déploiement importante : les jobs du palier 2 (analyse QBO,
 * facturation) peuvent tourner plusieurs minutes (stepDriver pilote une
 * boucle à intervalle 2s, jusqu'à 20 min de budget). Ça ne correspond PAS
 * au modèle "fonction serverless courte" — l'historique de marc-andre-app
 * documente déjà deux 504 pour cette exact raison côté app elle-même. Ce
 * serveur doit tourner comme un PROCESS PERSISTANT (petit VM, container,
 * Railway/Fly/Render...), pas comme une fonction Vercel classique à
 * durée de vie courte. Voir README.md.
 */
export function createApp() {
    const config = loadConfig();
    const logger = new Logger(config.logFile);
    const http = new MarcAndreHttpClient(config, logger);
    const app = express();
    app.use(express.json({ limit: '2mb' }));
    // Nettoyage périodique des jetons de confirmation expirés.
    setInterval(sweepExpiredIntents, 60_000).unref();
    app.get('/healthz', (_req, res) => {
        res.json({ ok: true, tier2Enabled: config.allowTier2, agentEnabled: config.agentEnabled });
    });
    const mcpRouter = express.Router();
    mcpRouter.use(requireAgentEnabled(config));
    mcpRouter.use(requireBearerAuth(config));
    mcpRouter.post('/', async (req, res) => {
        // Mode stateless : un serveur MCP neuf par requête, comme recommandé
        // par le SDK pour un déploiement HTTP sans affinité de session entre
        // requêtes. Les jetons de confirmation et le cache vivent au niveau du
        // process (modules confirm/intents.ts et core/cache.ts), pas ici.
        const server = new McpServer({ name: 'marc-andre-mcp', version: '0.1.0' });
        registerAllTools(server, config, http, logger);
        const transport = new StreamableHTTPServerTransport({
            sessionIdGenerator: () => randomUUID(),
        });
        res.on('close', () => {
            transport.close();
            server.close();
        });
        await server.connect(transport);
        await transport.handleRequest(req, res, req.body);
    });
    app.use('/mcp', mcpRouter);
    return { app, config, logger };
}

import { createHash, randomUUID } from 'node:crypto';
import { ConfirmationError } from '../core/errors.js';
const TTL_MS = 10 * 60 * 1000;
const store = new Map();
function hashParams(action, params) {
    return createHash('sha256')
        .update(action)
        .update('|')
        .update(JSON.stringify(params))
        .digest('hex');
}
export function createIntent(action, params, payload) {
    const token = randomUUID();
    store.set(token, {
        hash: hashParams(action, params),
        payload,
        createdAt: Date.now(),
        consumed: false,
    });
    return token;
}
export function consumeIntent(action, params, token) {
    const intent = store.get(token);
    if (!intent) {
        throw new ConfirmationError("Jeton de confirmation inconnu ou déjà utilisé. Relance l'étape de préparation.");
    }
    if (intent.consumed) {
        throw new ConfirmationError('Ce jeton a déjà été utilisé (usage unique).');
    }
    if (Date.now() - intent.createdAt > TTL_MS) {
        store.delete(token);
        throw new ConfirmationError('Ce jeton de confirmation a expiré (10 minutes). Relance l\'étape de préparation.');
    }
    if (intent.hash !== hashParams(action, params)) {
        throw new ConfirmationError('Les paramètres fournis ne correspondent plus à ce qui a été proposé. ' +
            "Relance l'étape de préparation avec les paramètres exacts que tu veux exécuter.");
    }
    intent.consumed = true;
    store.delete(token);
    return intent.payload;
}
/** Nettoyage périodique — évite une fuite mémoire lente sur un process long-lived. */
export function sweepExpiredIntents() {
    const now = Date.now();
    for (const [token, intent] of store) {
        if (now - intent.createdAt > TTL_MS)
            store.delete(token);
    }
}

import { timingSafeEqual } from 'node:crypto';
/**
 * Authentifie les appels ENTRANTS vers ce serveur MCP hébergé (distinct de
 * MA_AGENT_KEY, qui authentifie ce serveur AUPRÈS de marc-andre-app).
 *
 * Piège documenté à ne pas reproduire (vu dans app/api/cron/* de
 * marc-andre-app) : `if (secret && header !== attendu)` — si la variable
 * est absente, la route est OUVERTE. Ici la logique est inversée :
 * jeton absent ou mal formé ⇒ refus systématique, sans exception.
 *
 * Comparaison en temps constant pour éviter une fuite d'information par
 * mesure de timing sur la comparaison de chaînes.
 */
export function requireBearerAuth(config) {
    const expected = Buffer.from(config.mcpBearerToken, 'utf8');
    return function (req, res, next) {
        const header = req.header('authorization') ?? '';
        const match = /^Bearer (.+)$/.exec(header);
        if (!match) {
            res.status(401).json({ error: 'Authorization: Bearer <token> requis.' });
            return;
        }
        const provided = Buffer.from(match[1], 'utf8');
        // timingSafeEqual exige des buffers de même longueur — un mismatch de
        // longueur est déjà un refus, pas une exception à laisser fuiter.
        const ok = provided.length === expected.length && timingSafeEqual(provided, expected);
        if (!ok) {
            res.status(401).json({ error: 'Jeton invalide.' });
            return;
        }
        next();
    };
}
export function requireAgentEnabled(config) {
    return function (_req, res, next) {
        if (!config.agentEnabled) {
            res.status(503).json({
                error: "Agent désactivé (AGENT_ENABLED=false). Geste d'urgence actif — voir README pour le réactiver.",
            });
            return;
        }
        next();
    };
}

/**
 * Cache mémoire à durée de vie (TTL). Sert avant tout à protéger
 * marc-andre-app (donc SharePoint / Microsoft Graph / Asana / HubSpot en
 * amont) d'un agent qui interrogerait `ma_lister_clients` ou `ma_finance`
 * en boucle — un 429 Graph peut déconnecter des humains (bug documenté
 * dans lib/users.js côté marc-andre-app).
 *
 * Volontairement en mémoire process, pas distribué : ce serveur MCP est
 * censé tourner comme un service unique, pas une flotte d'instances.
 */
export class TtlCache {
    ttlMs;
    store = new Map();
    constructor(ttlMs) {
        this.ttlMs = ttlMs;
    }
    get(key) {
        const entry = this.store.get(key);
        if (!entry)
            return undefined;
        if (Date.now() > entry.expiresAt) {
            this.store.delete(key);
            return undefined;
        }
        return entry.value;
    }
    set(key, value, ttlMsOverride) {
        this.store.set(key, {
            value,
            expiresAt: Date.now() + (ttlMsOverride ?? this.ttlMs),
        });
    }
    invalidate(key) {
        this.store.delete(key);
    }
    clear() {
        this.store.clear();
    }
}

/**
 * Taxonomie d'erreurs. Chaque erreur porte un message FRANÇAIS,
 * ACTIONNABLE, jamais l'erreur brute d'origine (qui reste dans `.cause`
 * pour le journal local, mais n'est jamais renvoyée telle quelle à Claude).
 */
export class AgentError extends Error {
    code;
    constructor(code, message, options) {
        super(message, options);
        this.code = code;
        this.name = new.target.name;
    }
}
export class AuthError extends AgentError {
    constructor(message = 'Authentification refusée.', options) {
        super('AUTH_ERROR', message, options);
    }
}
export class ToolNotAllowedError extends AgentError {
    constructor(tool) {
        super('TOOL_NOT_ALLOWED', `L'outil « ${tool} » n'existe pas ou n'est pas autorisé dans la configuration actuelle ` +
            `(vérifie MA_ALLOW_TIER2 si c'est un outil du palier 2).`);
    }
}
export class ValidationError extends AgentError {
    constructor(message, options) {
        super('VALIDATION_ERROR', message, options);
    }
}
export class PreconditionError extends AgentError {
    constructor(message, options) {
        super('PRECONDITION_ERROR', message, options);
    }
}
export class UpstreamTimeoutError extends AgentError {
    constructor(tool, timeoutMs) {
        super('UPSTREAM_TIMEOUT', `marc-andre-app n'a pas répondu à temps pour « ${tool} » (${timeoutMs} ms). ` +
            `Réessaie dans un instant — si ça persiste, le service est peut-être en panne.`);
    }
}
export class UpstreamError extends AgentError {
    constructor(tool, status, detail, options) {
        super('UPSTREAM_ERROR', `marc-andre-app a refusé l'appel « ${tool} » (HTTP ${status}) : ${detail}`, options);
    }
}
export class ConfirmationError extends AgentError {
    constructor(message) {
        super('CONFIRMATION_ERROR', message);
    }
}
/** Convertit n'importe quelle erreur en texte affichable à Claude, sans fuite de détails internes. */
export function toDisplayMessage(err) {
    if (err instanceof AgentError)
        return err.message;
    if (err instanceof Error)
        return `Erreur inattendue : ${err.message}`;
    return 'Erreur inattendue.';
}

import { setTimeout as delay } from 'node:timers/promises';
import { UpstreamError, UpstreamTimeoutError } from './errors.js';
/**
 * SEUL module qui fait du réseau vers marc-andre-app. C'est ce qui rend
 * l'authentification, le caviardage, les délais et les reprises
 * vérifiables en un seul endroit — aucun `fetch` ne doit apparaître
 * ailleurs dans le projet.
 *
 * Contrat côté marc-andre-app attendu (spécifié dans PALIERS.md, PAS
 * encore implémenté — à faire au GO) :
 *   GET  /api/agent/health           → { ok, tier1, tier2Enabled, qboWriteEnabled, safeModeEmail }
 *   GET  /api/agent/tools            → catalogue des outils permis (source de vérité serveur)
 *   POST /api/agent/invoke           → { tool, input, requestId } → résultat de l'outil
 *
 * En-têtes envoyés sur CHAQUE appel (jamais de secret en query string —
 * contrairement au patron `?adminKey=` observé dans marc-andre-app, qui
 * finit dans les journaux de plateforme) :
 *   Authorization: Bearer <MA_AGENT_KEY>
 *   X-Agent-Id: <MA_AGENT_ID>
 *   X-Agent-Request-Id: <uuid>
 */
const RETRYABLE_STATUS = new Set([429, 502, 503, 504]);
const MAX_RETRIES = 3;
export class MarcAndreHttpClient {
    config;
    logger;
    constructor(config, logger) {
        this.config = config;
        this.logger = logger;
    }
    async invoke(tool, input, requestId, opts = {}) {
        const url = `${this.config.maBaseUrl}/api/agent/invoke`;
        const body = JSON.stringify({ tool, input, requestId });
        const timeoutMs = opts.timeoutMs ?? this.config.timeoutMs;
        let lastErr;
        for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
            if (attempt > 0) {
                const backoff = Math.min(2000 * 2 ** (attempt - 1), 8000) + Math.random() * 250;
                await delay(backoff);
            }
            const controller = new AbortController();
            const timer = setTimeout(() => controller.abort(), timeoutMs);
            try {
                const res = await fetch(url, {
                    method: 'POST',
                    headers: {
                        'content-type': 'application/json',
                        authorization: `Bearer ${this.config.maAgentKey}`,
                        'x-agent-id': this.config.maAgentId,
                        'x-agent-request-id': requestId,
                    },
                    body,
                    signal: controller.signal,
                });
                const raw = await res.text();
                if (!res.ok) {
                    if (RETRYABLE_STATUS.has(res.status) && attempt < MAX_RETRIES) {
                        await this.logger.warn('upstream_retry', { tool, status: res.status, attempt });
                        lastErr = new UpstreamError(tool, res.status, this.safeSnippet(raw));
                        continue;
                    }
                    throw new UpstreamError(tool, res.status, this.safeSnippet(raw));
                }
                // Garde « réponse non-JSON » — même piège que parseJsonResponse()
                // côté page client de marc-andre-app (page d'erreur Vercel HTML
                // renvoyée avec un statut 200, ou un timeout de plateforme muet).
                try {
                    return JSON.parse(raw);
                }
                catch {
                    throw new UpstreamError(tool, res.status, `réponse non-JSON reçue (${this.safeSnippet(raw)}) — probable erreur de plateforme amont`);
                }
            }
            catch (err) {
                if (err instanceof UpstreamError)
                    throw err;
                if (err?.name === 'AbortError') {
                    throw new UpstreamTimeoutError(tool, timeoutMs);
                }
                lastErr = err;
                if (attempt >= MAX_RETRIES) {
                    throw new UpstreamError(tool, 0, 'échec réseau après plusieurs tentatives', {
                        cause: err,
                    });
                }
            }
            finally {
                clearTimeout(timer);
            }
        }
        throw lastErr instanceof Error
            ? lastErr
            : new UpstreamError(tool, 0, 'échec inconnu après retries');
    }
    async health() {
        return this.invoke('__health__', {}, 'health-check');
    }
    safeSnippet(raw) {
        return raw.length > 200 ? raw.slice(0, 200) + '…' : raw;
    }
}

import { appendFile } from 'node:fs/promises';
import { redact } from './redact.js';
export class Logger {
    filePath;
    constructor(filePath) {
        this.filePath = filePath;
    }
    async write(entry) {
        const safe = redact(entry);
        const line = JSON.stringify(safe) + '\n';
        process.stderr.write(line);
        try {
            await appendFile(this.filePath, line, 'utf8');
        }
        catch {
            // Le journal local ne doit jamais faire échouer l'action métier
            // appelante — même règle que logAction() côté marc-andre-app.
        }
    }
    info(event, data = {}) {
        return this.write({ ts: new Date().toISOString(), level: 'info', event, ...data });
    }
    warn(event, data = {}) {
        return this.write({ ts: new Date().toISOString(), level: 'warn', event, ...data });
    }
    error(event, data = {}) {
        return this.write({ ts: new Date().toISOString(), level: 'error', event, ...data });
    }
}

/**
 * Caviardage récursif des secrets/PII avant tout log. Testé unitairement
 * (test/redact.test.ts) — aucun secret ne doit franchir le logger.
 */
const SENSITIVE_KEY_PATTERN = /token|key|secret|password|authorization|bearer|adminkey|staff/i;
export function redact(value, depth = 0) {
    if (depth > 6)
        return '[tronqué]';
    if (typeof value === 'string') {
        // Redacte aussi les jetons qui traînent dans une chaîne libre
        // (ex: une URL avec ?adminKey=... collée dans un message d'erreur amont).
        return value.replace(/github_pat_[A-Za-z0-9_]{20,}/g, 'github_pat_[REDACTED]');
    }
    if (Array.isArray(value)) {
        return value.map((v) => redact(v, depth + 1));
    }
    if (value && typeof value === 'object') {
        const out = {};
        for (const [k, v] of Object.entries(value)) {
            if (SENSITIVE_KEY_PATTERN.test(k)) {
                out[k] = '[REDACTED]';
            }
            else {
                out[k] = redact(v, depth + 1);
            }
        }
        return out;
    }
    return value;
}

/** Libellés français alignés sur le vocabulaire déjà utilisé dans marc-andre-app. */
export const STATUT_JOB_FR = {
    queued: 'en file d\'attente',
    collecting: 'collecte des données en cours',
    analyzing: 'analyse en cours',
    'ready-for-review': 'prêt pour révision',
    error: 'en erreur',
};
export const DOC_STATUS_FR = {
    complet: 'dossier complet',
    archive: 'archivé',
    documents_recus: 'documents reçus',
    en_attente: 'en attente de documents',
    pas_traite: 'pas encore traité',
};
export function labelStatutJob(status) {
    return STATUT_JOB_FR[status] ?? status;
}

/**
 * Compaction des réponses volumineuses avant de les rendre à Claude.
 * Règle : toute troncature est ANNONCÉE explicitement, jamais muette
 * (voir §3.1 du rapport — `raw`, `doublonStats.tablesTronquees`, etc.).
 */
export function stripRawFields(items) {
    return items.map(({ raw, ...rest }) => rest);
}
export function truncateList(items, max) {
    if (items.length <= max) {
        return { items, truncated: false, totalAvant: items.length };
    }
    return { items: items.slice(0, max), truncated: true, totalAvant: items.length };
}
/**
 * Élagage par sections pour ma_fiche_client : la route sous-jacente
 * renvoie TOUT (hubspot, quickbooks, docusign, threads, mandats, jobs,
 * depots, registres) ; le paramètre `sections` n'existe pas côté route,
 * c'est un filtrage fait ICI, côté passerelle.
 */
export function pickSections(full, sections, sectionKeyMap) {
    if (!sections || sections.length === 0)
        return full;
    const keysToKeep = new Set();
    for (const s of sections) {
        for (const k of sectionKeyMap[s] ?? [])
            keysToKeep.add(k);
    }
    const out = {};
    for (const key of Object.keys(full)) {
        if (keysToKeep.has(key))
            out[key] = full[key];
    }
    return out;
}

import { setTimeout as delay } from 'node:timers/promises';
import { PreconditionError } from '../core/errors.js';
export async function driveJobToCompletion(http, stepTool, stepInput, requestId, logger, opts = {}) {
    const intervalMs = opts.intervalMs ?? 2000;
    const maxIterations = opts.maxIterations ?? 300;
    const maxDurationMs = opts.maxDurationMs ?? 20 * 60 * 1000;
    const start = Date.now();
    let lastSeen = null;
    let stuckCount = 0;
    for (let i = 0; i < maxIterations; i++) {
        if (Date.now() - start > maxDurationMs) {
            throw new PreconditionError(`Budget de temps de la passerelle dépassé (${Math.round(maxDurationMs / 60000)} min). Le job côté marc-andre-app N'EST PAS annulé : il se libérera ` +
                `de lui-même après la période d'inactivité prévue par l'application, ou ` +
                `reprend si la fiche client est ouverte dans le navigateur.`);
        }
        const result = await http.invoke(stepTool, stepInput, requestId);
        opts.onProgress?.(result);
        await logger.info('job_step', { stepTool, status: result.status, iteration: i });
        if (result.done)
            return result;
        // Détection de blocage : même statut renvoyé N fois de suite sans
        // progression — mieux vaut le dire à Claude que de tourner en boucle
        // muette jusqu'au plafond.
        const marker = JSON.stringify({ status: result.status, phase: result.collectPhase ?? result.analysisPhase });
        if (marker === lastSeen) {
            stuckCount++;
            if (stuckCount > 30) {
                // ~1 min sans changement d'état apparent à intervalle 2s
                await logger.warn('job_step_stuck', { stepTool, status: result.status });
            }
        }
        else {
            stuckCount = 0;
            lastSeen = marker;
        }
        await delay(intervalMs);
    }
    throw new PreconditionError(`Le job n'a pas atteint son état final après ${maxIterations} étapes. ` +
        `Utilise l'outil de progression pour vérifier son statut actuel — il continuera ` +
        `d'avancer si la fiche client est ouverte dans marc-andre-app.`);
}

import { z } from 'zod';
/** sessionToken = clé primaire de tout le système côté marc-andre-app (§1.5). */
export const sessionToken = z.string().min(8).describe("Jeton de session du client (retourné par ma_chercher_client ou ma_lister_clients). " +
    'Ce n\'est pas un identifiant lisible — toujours obtenu via un autre outil, jamais inventé.');
export const dateStr = z
    .string()
    .regex(/^\d{4}-\d{2}-\d{2}$/, 'Format attendu : YYYY-MM-DD')
    .describe('Date au format YYYY-MM-DD');
export const pagination = {
    page: z.number().int().min(1).default(1).optional(),
    pageSize: z.number().int().min(1).max(100).default(25).optional(),
};

import { randomUUID } from 'node:crypto';
import { ToolNotAllowedError, toDisplayMessage } from '../core/errors.js';
import { tier1ClientTools } from './tier1/clients.js';
import { tier1EcrituresTools } from './tier1/ecritures.js';
import { tier1QuickbooksTools } from './tier1/quickbooks.js';
import { tier1AdminTools } from './tier1/admin.js';
import { tier2QboTools } from './tier2/qboAnalyse.js';
import { tier2FacturationTools } from './tier2/facturation.js';
import { tier2RelanceTools } from './tier2/relance.js';
/**
 * UNE seule allowlist, codée en dur (§2.2/§2.4). Un outil absent de cette
 * table n'existe pas pour Claude — pas de 404 en aval à masquer, il n'est
 * simplement jamais enregistré sur le serveur MCP.
 *
 * Le palier 2 n'est ajouté à la liste que si config.allowTier2 === true :
 * les outils ne sont pas "présents mais refusés", ils sont ABSENTS du
 * catalogue. Claude ne peut pas être tenté par un outil qu'il ne voit pas.
 */
export function buildToolList(config) {
    const tier1 = [
        ...tier1ClientTools,
        ...tier1EcrituresTools,
        ...tier1QuickbooksTools,
        ...tier1AdminTools,
    ];
    if (!config.allowTier2)
        return tier1;
    return [...tier1, ...tier2QboTools, ...tier2FacturationTools, ...tier2RelanceTools];
}
function checkClientAllowlist(config, input) {
    if (!config.allowedClients)
        return;
    const st = input?.sessionToken;
    if (st && !config.allowedClients.includes(st)) {
        throw new ToolNotAllowedError(`sessionToken hors de la liste pilote AGENT_ALLOWED_CLIENTS (décision D8)`);
    }
}
export function registerAllTools(server, config, http, logger) {
    const tools = buildToolList(config);
    for (const def of tools) {
        server.registerTool(def.name, {
            title: def.name,
            description: `[palier ${def.tier}${def.requiresAdmin ? ', requireAdmin côté app' : ''}] ${def.description}`,
            inputSchema: def.inputSchema,
        }, async (input) => {
            const requestId = randomUUID();
            const ctx = { http, logger, config, requestId };
            try {
                checkClientAllowlist(config, input);
                await logger.info('tool_call_start', { tool: def.name, requestId });
                const result = def.localHandler
                    ? await def.localHandler(input, ctx)
                    : await (async () => {
                        const raw = await http.invoke(def.action, input, requestId);
                        return def.postProcess ? await def.postProcess(raw, input, ctx) : raw;
                    })();
                await logger.info('tool_call_success', { tool: def.name, requestId });
                return {
                    content: [{ type: 'text', text: JSON.stringify(result, null, 2) }],
                };
            }
            catch (err) {
                await logger.error('tool_call_error', {
                    tool: def.name,
                    requestId,
                    message: toDisplayMessage(err),
                });
                return {
                    content: [{ type: 'text', text: `Erreur : ${toDisplayMessage(err)}` }],
                    isError: true,
                };
            }
        });
    }
    logger.info('tools_registered', {
        count: tools.length,
        tier2Enabled: config.allowTier2,
        names: tools.map((t) => t.name),
    });
}

